class Doc:
    def __init__(self):
        self._text = ''
        self._done = []
        self._undone = []
        self._depth = 0
        self._group = None

    def text(self):
        return self._text

    def begin_group(self):
        self._depth += 1
        if self._depth == 1:
            self._group = []

    def end_group(self):
        if self._depth <= 0:
            raise RuntimeError('no group open')
        self._depth -= 1
        if self._depth == 0:
            group = self._group
            self._group = None
            if group:
                self._done.append(('group', group))
                self._undone = []

    def _apply(self, edit):
        kind, pos, s = edit
        if kind == 'insert':
            self._text = self._text[:pos] + s + self._text[pos:]
        else:
            self._text = self._text[:pos] + self._text[pos + len(s):]

    def _invert(self, edit):
        kind, pos, s = edit
        return ('delete' if kind == 'insert' else 'insert', pos, s)

    def _record(self, edit):
        if self._depth > 0:
            self._group.append(edit)
        else:
            self._done.append(edit)
            self._undone = []

    def insert(self, pos, s):
        if pos < 0 or pos > len(self._text):
            raise IndexError(pos)
        edit = ('insert', pos, s)
        self._apply(edit)
        self._record(edit)

    def delete(self, pos, n):
        if n < 0 or pos < 0 or pos + n > len(self._text):
            raise IndexError(pos)
        edit = ('delete', pos, self._text[pos:pos + n])
        self._apply(edit)
        self._record(edit)

    def undo(self):
        if self._depth > 0:
            raise RuntimeError('group open')
        if not self._done:
            return
        step = self._done.pop()
        if step[0] == 'group':
            for edit in reversed(step[1]):
                self._apply(self._invert(edit))
        else:
            self._apply(self._invert(step))
        self._undone.append(step)

    def redo(self):
        if self._depth > 0:
            raise RuntimeError('group open')
        if not self._undone:
            return
        step = self._undone.pop()
        if step[0] == 'group':
            for edit in step[1]:
                self._apply(edit)
        else:
            self._apply(step)
        self._done.append(step)

